#!/usr/bin/env python3
"""Terminal image viewer implemented independently from observable behavior."""
import os,sys,math,time,socket,urllib.parse,signal
from cli import parse,resource,UsageError
from images import decode,BadImage
from symbols import Renderer
import protocols

def write(text):
    sys.stdout.buffer.write(text.encode('utf-8','replace'))
    sys.stdout.buffer.flush()

def error(message):
    sys.stderr.write(f'{sys.argv[0]}: {message}\n')
    sys.stderr.flush()

def label(fn,width,o):
    name=os.path.basename(fn) if fn!='-' else '-'
    if len(name)>width: name=name[:max(0,width-1)]+'…'
    prefix=suffix=''
    if o.link is True or (o.link=='auto' and o.ansi and not o.polite and o.unicode):
        target='file://'+socket.gethostname()+urllib.parse.quote(os.path.abspath(fn),safe='/')
        if o.ansi: prefix='\x1b]8;;'+target+'\x1b\\';suffix='\x1b]8;;\x1b\\'
        else: prefix=target
    return prefix+name+suffix+' '*max(0,width-len(name))

def frame(im,fn,o,renderer,grid=None):
    w,h=o.geometry(im.w,im.h,grid)
    if w*h>2000000: raise BadImage()
    vw,vh=o.available
    alignx,aligny=o.align
    x=max(0,vw-w)//2 if alignx=='mid' else max(0,vw-w) if alignx=='right' else 0
    y=max(0,vh-h-int(bool(o.label)))//2 if aligny=='mid' else max(0,vh-h-int(bool(o.label))) if aligny=='bottom' else 0
    out=''
    if y:
        if o.relative:
            if o.ansi: out+='\x1bD'*y
        else: out+='\n'*y
    def pad():
        if o.relative: return f'\x1b[{x}C' if x and o.ansi else ''
        return ' '*x
    if o.format=='symbols':
        canvas=renderer.canvas(im,w,h)
        for i,row in enumerate(canvas):
            if i:
                if o.relative:
                    if o.ansi: out+=f'\x1b[{w+x}D\x1bD'
                else: out+='\n'
            out+=pad()+renderer.encode_row(row,i==0)
    else:
        out+=pad()+protocols.encode(im,w,h,o)
    if o.relative:
        out+='\x1bD'
        if o.ansi: out+=f'\x1b[{w+x}D'
    else:
        out+='\r\n' if y+h>=o.view[1] else '\n'
    if o.label:
        out+=label(fn,vw,o)
        out+='\x1bD'+(f'\x1b[{vw}D' if o.ansi else '') if o.relative else '\n'
    return out,w,h+y+int(bool(o.label))

def grid_output(items,o,r):
    vw,vh=o.available;gw,gh=o.grid
    if gw=='auto': gw,gh=4,-1
    if gw<0:
        rh=max(1,vh//max(1,gh)-1-int(bool(o.label)))
        gw=max(1,vw//(rh*2+2))
    cw=max(1,vw//gw-1)
    ch=max(1,vh//gh-1-int(bool(o.label))) if gh and gh>0 else max(1,int(cw*o.font_ratio))
    output=''
    for groupidx in range(0,len(items),gw):
        group=items[groupidx:groupidx+gw];images=[];height=0
        for fn,im in group:
            w,h=o.geometry(im.w,im.h,(cw,ch));height=max(height,h)
            images.append((fn,w,h,r.canvas(im,w,h)))
        for y in range(height):
            for j,(fn,w,h,canvas) in enumerate(images):
                left=(cw-w)//2
                if y<h:
                    output+=' '*left+r.encode_row(canvas[y],True)+' '*(cw-w-left)
                else: output+=' '*cw
                output+=' '
            output+='\n'
        if o.label:
            for fn,w,h,canvas in images: output+=label(fn,cw,o)+' '
            output+='\n'
        output+='\n'
    return output

def main():
    try:
        o=parse(sys.argv[1:])
        if o.help:
            write(resource('help.txt').decode().replace('./executable',sys.argv[0],1));return 0
        if o.version: write(resource('version.txt').decode());return 0
        o.finish();renderer=Renderer(o)
    except UsageError as e:
        error(str(e));return 2
    if o.cursor: write('\x1b[?25l')
    failures=0;success=0;griditems=[];stdin_data=None
    try:
        for fn in o.files:
            try:
                if fn=='-':
                    if stdin_data is None: stdin_data=sys.stdin.buffer.read()
                    data=stdin_data
                    if not data: raise OSError('Could not cache input stream')
                elif os.path.isdir(fn): raise BadImage()
                else:
                    with open(fn,'rb') as f: data=f.read()
                frames=decode(data)
            except OSError as e:
                msg=e.strerror if e.strerror else str(e)
                error(f"Failed to open '{fn}': {msg}");failures+=1;continue
            except BadImage:
                error(f"Failed to open '{fn}': Unknown file format");failures+=1;continue
            if o.grid:
                griditems.append((fn,frames[0]));success+=1;continue
            if o.clear:
                if o.ansi: write('\x1b[2J\x1b[0H')
            elif success: write('\x1bD' if o.relative else '\n')
            start=time.monotonic();prevheight=0;cycles=0
            if not o.animate: frames=frames[:1]
            duration=o.duration
            if duration is None: duration=math.inf if len(o.files)==1 and len(frames)>1 else 0
            if len(frames)==1:
                text,w,h=frame(frames[0],fn,o,renderer);write(text)
                if o.watch:
                    # Monitoring starts with an initial refresh, then polls for
                    # modifications until its duration expires.
                    if o.ansi: write(f'\x1b[{h}A')
                    write(text)
                    remaining=duration-(time.monotonic()-start)
                    if duration!=math.inf and remaining>0: time.sleep(min(remaining,20))
                elif duration and math.isfinite(duration): time.sleep(min(duration,20))
            else:
                while True:
                    for im in frames:
                        if prevheight and o.ansi: write(f'\x1b[{prevheight}A')
                        text,w,h=frame(im,fn,o,renderer);write(text);prevheight=h
                        delay=im.delay/1000
                        if isinstance(o.speed,tuple): delay=1/o.speed[1]
                        elif o.speed: delay/=o.speed
                        if delay>0: time.sleep(delay)
                    cycles+=1
                    if time.monotonic()-start>=duration: break
            success+=1
        if griditems: write(grid_output(griditems,o,renderer))
    except (KeyboardInterrupt,BrokenPipeError): pass
    finally:
        if o.cursor:
            try: write('\x1b[?25h')
            except BrokenPipeError: pass
    return 2 if failures and not success else 1 if failures else 0

if __name__=='__main__':
    try: sys.exit(main())
    except BrokenPipeError: sys.exit(0)
