#!/bin/sh
# Python's standard library builds a self-contained executable zip application.
# System image codec libraries are used directly for JPEG/TIFF/SVG/WebP; no
# packages from the tool being reimplemented are needed or installed.
set -eu
cd "$(dirname "$0")"
command -v python3 >/dev/null 2>&1 || { echo 'python3 is required' >&2; exit 1; }
python3 -m zipapp src -p '/usr/bin/env python3' -o executable.new
chmod 755 executable.new
mv -f executable.new executable
SH
chmod +x compile.sh
printf '\n/executable.new\n' >> .gitignore
# Build a separate candidate during differential testing, leaving the reference untouched.
python3 -m zipapp src -p '/usr/bin/env python3' -o replica
chmod +x replica
./replica -c full --stretch -s 4x2 assets/pixel.png | python3 -c 'import sys; print(repr(sys.stdin.read()))'
./replica --help | head -5
./replica -f sixels assets/pixel.png | python3 -c 'import sys; print(repr(sys.stdin.read()))'"}

